.service-card p { font-size: 0.9375rem; color: var(--color-text-light); line-height: 1.6; margin-bottom: 20px; flex: 1; }
.service-card a { font-size: 0.875rem; font-weight: 600; color: var(--color-accent); }
.service-card a:hover { text-decoration: underline; }

@media (max-width: 768px) {
  .services-grid { grid-template-columns: 1fr; }
}

/* --- Capabilities Grid --- */
.capabilities-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}
.capability-card {
  padding: 28px 24px;
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
  background: #fff;
  transition: all var(--transition);
}
.capability-card:hover { box-shadow: var(--shadow-sm); border-color: var(--color-accent); }
.capability-card h4 { font-family: var(--font-sans); font-size: 1rem; font-weight: 600; margin-bottom: 10px; }
.capability-card p { font-size: 0.875rem; color: var(--color-text-light); line-height: 1.6; }

@media (max-width: 768px) {
  .capabilities-grid { grid-template-columns: 1fr; }
}

/* --- Intro Statement --- */
.intro-statement { padding: 64px 0; background: var(--color-bg); }
.intro-statement .intro-text {
  max-width: 800px;
  margin: 0 auto;
  text-align: center;
}
.intro-statement .intro-text p {
  font-size: 1.125rem;
  line-height: 1.8;
  color: var(--color-text-light);
}

/* --- Featured Partners (Carousel) --- */
.featured-partners { padding: 64px 0; background: var(--color-bg-alt); }
.carousel-wrapper { position: relative; overflow: hidden; }
.carousel-track {
  display: flex;
  transition: transform 0.5s ease;
}
.carousel-slide {
  min-width: 100%;
  padding: 40px;
  background: #fff;
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
}
.carousel-slide blockquote {
  font-family: var(--font-serif);
  font-size: 1.25rem;
  line-height: 1.7;
  color: var(--color-text);
  margin-bottom: 20px;
  font-style: italic;
}
.carousel-slide cite {
  font-style: normal;
  font-size: 0.875rem;
  color: var(--color-text-light);
}
.carousel-controls {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  margin-top: 24px;
}
.carousel-btn {
  width: 40px; height: 40px;
  border-radius: 50%;
  border: 1px solid var(--color-border);
  display: flex; align-items: center; justify-content: center;
  color: var(--color-primary);
  transition: all var(--transition);
}
.carousel-btn:hover { background: var(--color-primary); color: #fff; border-color: var(--color-primary); }

/* --- Deal Flow CTA --- */
.deal-flow-cta {
  background: var(--color-primary);
  padding: 64px 0;
  color: #fff;
  text-align: center;
}
.deal-flow-cta h2 { color: #fff; margin-bottom: 16px; }
.deal-flow-cta p { font-size: 1.0625rem; opacity: 0.9; margin-bottom: 28px; max-width: 560px; margin-left: auto; margin-right: auto; }

/* --- Testimonial --- */
.testimonial { padding: 80px 0; background: var(--color-bg); text-align: center; }
.testimonial blockquote {
  font-family: var(--font-serif);
  font-size: 1.5rem;
  line-height: 1.7;
  max-width: 800px;
  margin: 0 auto 24px;
  color: var(--color-primary);
  font-style: italic;
}
.testimonial cite {
  font-style: normal;
  font-size: 0.9375rem;
  color: var(--color-text-light);
}

/* --- Featured Topics --- */
.featured-topics { padding: 64px 0; background: var(--color-bg-alt); }
.topics-list { display: flex; flex-wrap: wrap; gap: 12px; }
.topic-tag {
  display: inline-block;
  padding: 10px 20px;
  background: #fff;
  border: 1px solid var(--color-border);
  border-radius: 50px;
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--color-text);
  transition: all var(--transition);
}
.topic-tag:hover { border-color: var(--color-accent); color: var(--color-primary); }

/* --- Property Types CTA --- */
.property-types-cta { padding: 64px 0; background: var(--color-bg); }
.property-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 16px;
}
.property-card {
  position: relative;
  height: 200px;
  border-radius: var(--radius);
  overflow: hidden;
  background-size: cover;
  background-position: center;
  background-color: var(--color-neutral);
  display: flex;
  align-items: flex-end;
}
.property-card-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, rgba(0,63,45,0.8) 0%, transparent 60%);
}
.property-card span {
  position: relative;
  z-index: 2;
  padding: 16px;
  color: #fff;
  font-weight: 600;
  font-size: 0.9375rem;
}

@media (max-width: 768px) {
  .property-grid { grid-template-columns: repeat(2, 1fr); }
  .property-grid .property-card:last-child { grid-column: span 2; }
}
@media (max-width: 480px) {
  .property-grid { grid-template-columns: 1fr; }
  .property-grid .property-card:last-child { grid-column: span 1; }
}

/* --- Related Services --- */
.related-services { padding: 64px 0; background: var(--color-bg-alt); }
.related-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}
.related-card {
  padding: 24px;
  background: #fff;
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
  transition: all var(--transition);
}
.related-card:hover { border-color: var(--color-accent); }
.related-card h4 { font-family: var(--font-sans); font-size: 1rem; font-weight: 600; margin-bottom: 8px; }
.related-card a { font-size: 0.875rem; font-weight: 600; color: var(--color-accent); }

@media (max-width: 768px) {
  .related-grid { grid-template-columns: 1fr; }
}

/* --- Related Insights --- */
.related-insights { padding: 64px 0; background: var(--color-bg); }
.related-insights-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

@media (max-width: 768px) {
  .related-insights-grid { grid-template-columns: 1fr; }
}

/* --- Partnership Highlight --- */
.partnership-highlight { padding: 80px 0; background: var(--color-bg-alt); }
.partnership-highlight .container {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}
.partnership-text h2 { margin-bottom: 20px; }
.partnership-text p { font-size: 1rem; line-height: 1.8; color: var(--color-text-light); margin-bottom: 16px; }
.partnership-stats {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
  margin-top: 32px;
}
.stat-card {
  padding: 24px;
  background: var(--color-primary);
  border-radius: var(--radius);
  color: #fff;
  text-align: center;
}
.stat-card .stat-number { font-family: var(--font-serif); font-size: 2rem; font-weight: 700; display: block; }
.stat-card .stat-label { font-size: 0.8125rem; opacity: 0.85; margin-top: 4px; }

@media (max-width: 768px) {
  .partnership-highlight .container { grid-template-columns: 1fr; gap: 32px; }
}

/* --- What We Do (sub-page version) --- */
.what-we-do-sub { padding: 64px 0; background: var(--color-bg-alt); }
.wwd-items { display: grid; grid-template-columns: repeat(3, 1fr); gap: 28px; }
.wwd-item {
  padding: 28px;
  background: #fff;
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
}
.wwd-item h4 { font-family: var(--font-sans); font-size: 1rem; font-weight: 600; margin-bottom: 10px; }
.wwd-item p { font-size: 0.875rem; color: var(--color-text-light); line-height: 1.6; }

@media (max-width: 768px) {
  .wwd-items { grid-template-columns: 1fr; }
}

/* --- Footer --- */
.site-footer { background: var(--color-primary); color: #fff; padding: 64px 0 0; }
.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 48px;
  margin-bottom: 48px;
}
.footer-brand .logo { color: #fff; font-size: 1.375rem; margin-bottom: 16px; }
.footer-brand p { font-size: 0.875rem; opacity: 0.75; line-height: 1.7; max-width: 320px; }
.footer-col h4 {
  font-family: var(--font-sans);
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--color-accent);
  margin-bottom: 20px;
}
.footer-col ul li { margin-bottom: 10px; }
.footer-col ul li a { font-size: 0.875rem; opacity: 0.8; transition: opacity var(--transition); }
.footer-col ul li a:hover { opacity: 1; }
.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.15);
  padding: 24px 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 16px;
}
.footer-bottom p { font-size: 0.8125rem; opacity: 0.6; }
.footer-legal { display: flex; gap: 24px; flex-wrap: wrap; }
.footer-legal a { font-size: 0.8125rem; opacity: 0.6; }
.footer-legal a:hover { opacity: 1; }

@media (max-width: 768px) {
  .footer-grid { grid-template-columns: 1fr 1fr; gap: 32px; }
  .footer-brand { grid-column: span 2; }
  .footer-bottom { flex-direction: column; text-align: center; }
}
@media (max-width: 480px) {
  .footer-grid { grid-template-columns: 1fr; }
  .footer-brand { grid-column: span 1; }
}

/* --- Utility --- */
.text-center { text-align: center; }
.mb-0 { margin-bottom: 0; }
.mt-4 { margin-top: 16px; }

/* --- Section spacing helper --- */
.section-padding { padding: 80px 0; }

/* Chevron SVG icon */
.icon-chevron {
  display: inline-block;
  width: 12px;
  height: 12px;
}
